import React from 'react'
/* Code-built hero scene: every shape below is generated by this file (SVG geometry + CSS keyframes). No video, no raster.
   Coordinate space 1671x941. Dome centre/radius, waterline and fortress axis are the composition anchors. */
export const DOME = { cx: 1039, cy: 583, r: 295 }
const BASE = 716, WATER = 739, FX = 1018                       // shoreline y, waterline y, fortress axis x
const deg = (a) => a * Math.PI / 180
export const rim = (a, r = DOME.r) => [DOME.cx + r * Math.cos(deg(a)), DOME.cy + r * Math.sin(deg(a))]
const f = (n) => +n.toFixed(1)

// Deterministic pseudo-random so the skyline is identical on every load (no layout or visual jitter).
const mk = (seed) => () => (seed = (seed * 1664525 + 1013904223) >>> 0) / 4294967296
function skyline(seed, minW, maxW, minH, maxH, lowZone) {
  const r = mk(seed), rects = [], win = { warm: '', cool: '', pale: '' }
  const towers = lowZone ? [] : [[545,38,150],[480,26,100],[625,30,96],[700,30,88],[1395,28,102],[1510,30,106],[1560,36,166],[1630,34,126],[300,30,80],[180,34,70],[60,40,64]]
  towers.forEach(([x, w, h]) => rects.push({ x, w, h }))
  for (let x = -10; x < 1690; x += 2 + r() * 4) {
    const w = minW + r() * (maxW - minW); const mid = x > 730 && x < 1320
    if (lowZone && !mid && r() < .12) { x += w; continue }
    if (!lowZone && mid) { x += w; continue }                  // the fortress owns the centre of the near layer
    rects.push({ x, w, h: mid ? 16 + r() * 30 : minH + r() * (maxH - minH) }); x += w
  }
  rects.forEach(b => { const y = BASE - b.h
    for (let row = 0; row < Math.floor(b.h / 9); row++) for (let c = 0; c < Math.floor(b.w / 7); c++) if (r() < .26) {
      const k = r(), key = k < .45 ? 'warm' : k < .85 ? 'cool' : 'pale'; win[key] += `M${f(b.x + 3 + c * 7)} ${f(y + 5 + row * 9)}h2v3h-2z` } })
  return { rects, win }
}
const FAR = skyline(11, 14, 42, 40, 150, true), NEAR = skyline(97, 22, 54, 22, 96, false)
const shoreR = mk(5); const shore = [], reflect = []
for (let x = 4; x < 1671; x += 9 + shoreR() * 6) if (shoreR() < .6) { const y = 721 + shoreR() * 8; shore.push([x, y]); if (shoreR() < .3) reflect.push([x, 14 + shoreR() * 52]) }
const starR = mk(3); const STARS = Array.from({ length: 46 }, () => [starR() * 1671, starR() * 420, .5 + starR() * .6, .25 + starR() * .35])
const CLOUDS = [[[170,230,260,38,-6],[360,160,300,30,4],[90,330,220,28,-3],[560,120,200,22,2]], [[1500,120,330,46,-5],[1420,260,300,36,3],[1600,330,260,34,-2],[1250,70,260,26,4],[1330,380,240,26,2]]]

// ---- fortress: stepped tiers + spire (all rects/polygons; windows from one SVG pattern) ----
const TIERS = [[470,36],[410,58],[340,62],[280,70],[222,72],[170,72],[120,70],[72,58]]
let y = BASE; const tiers = TIERS.map(([w, h]) => { y -= h; return { w, h, y } })
const TOP = tiers[tiers.length - 1].y, TIP = 98
const fl = (a) => a.map(v => f(v)).join(' ')
function Fortress() {
  return <g>
    {tiers.map((t, i) => <g key={i}>
      <rect x={FX - t.w / 2} y={t.y} width={t.w} height={t.h} fill="url(#towerFill)"/>
      <rect x={FX - t.w / 2} y={t.y} width={t.w} height={t.h} fill="url(#win)" opacity={.95 - i * .05}/>
      <path d={`M${f(FX - t.w / 2)} ${f(t.y + t.h)}V${f(t.y)}H${f(FX + t.w / 2)}V${f(t.y + t.h)}`} fill="none" stroke="#5fd9ee" strokeOpacity={.5} strokeWidth="1.2"/>
    </g>)}
    <polygon points={fl([FX - 13, TOP, FX, TIP, FX + 13, TOP])} fill="#0c1826" stroke="#5fd9ee" strokeOpacity=".6" strokeWidth="1"/>
    <rect x={FX - 2} y={TIP - 56} width="4" height={TOP - TIP + 56} fill="url(#spire)"/>
    <rect x={FX - 9} y={300} width="18" height={BASE - 300} fill="url(#spine)"/>
    {[-1, 1].map(s => [0, 1, 2].map(i => <rect key={s + '' + i} x={FX + s * (66 + i * 58) - 2} y={BASE - 150 - i * 56} width="4" height={150 + i * 56 - 36} fill="#22d3ee" opacity=".16"/>))}
    {/* low podium and forecourt */}
    <rect x={FX - 330} y={BASE - 18} width="660" height="18" fill="#08111b"/><path d={`M${FX - 330} ${BASE - 18}H${FX + 330}`} stroke="#5fd9ee" strokeOpacity=".35"/>
    <rect x={FX - 40} y={BASE - 14} width="80" height="14" fill="#22d3ee" opacity=".55"/>
    <g className="emb"><path d={`M${FX} 510 ${FX - 26} 521v24c0 18 13 32 26 38 13-6 26-20 26-38v-24z`} fill="#06131c" stroke="#22d3ee" strokeWidth="2.4"/>
      <path d={`M${FX - 8} 530h17M${FX - 8} 530v26M${FX - 8} 542h12`} stroke="#22d3ee" strokeWidth="3" fill="none"/></g>
  </g>
}
const Blocks = ({ d, fill }) => d.rects.map((b, i) => <rect key={i} x={f(b.x)} y={f(BASE - b.h)} width={f(b.w)} height={f(b.h + 24)} fill={fill}/>)
const City = ({ d, fill }) => <g><Blocks d={d} fill={fill}/><path d={d.win.warm} fill="#e3a559" opacity=".9"/><path d={d.win.cool} fill="#7fd6e6" opacity=".75"/><path d={d.win.pale} fill="#d9e6ee" opacity=".65"/></g>

const DP = `M${f(DOME.cx - 263.3)} ${BASE}A${DOME.r} ${DOME.r} 0 1 1 ${f(DOME.cx + 263.3)} ${BASE}`
const RING = { cx: DOME.cx, cy: 628, rx: 372, ry: 86, rot: -11 }
const ringD = (front) => `M${RING.cx - RING.rx} ${RING.cy}A${RING.rx} ${RING.ry} 0 0 ${front ? 0 : 1} ${RING.cx + RING.rx} ${RING.cy}`
const arc = (a1, a2, r = DOME.r) => { const [x1, y1] = rim(a1, r), [x2, y2] = rim(a2, r); return `M${f(x1)} ${f(y1)}A${r} ${r} 0 0 1 ${f(x2)} ${f(y2)}` }

// One incoming threat: tapered red trail flying along its own axis, then impact sparks, rim ripple and a shield reaction.
function Threat({ hit, ang = 20, t0 = 0, fly = 1.1 }) {
  const [x, y] = rim(hit), d = (s) => ({ animationDelay: `${t0 + fly + s}s` })
  const sparks = [-70, -38, -8, 24, 58, 96].map((a, i) => ({ a, l: 22 + (i % 3) * 10 }))
  return <g transform={`translate(${f(x)} ${f(y)})`}>
    <g transform={`rotate(${ang})`}><g className="fly" style={{ animationDelay: `${t0}s`, animationDuration: `${fly}s` }}>
      <line x1="-460" y1="0" x2="0" y2="0" stroke="#ef4444" strokeOpacity=".4" strokeWidth="1.3"/>
      <polygon points="-230,0 0,-3.4 8,0 0,3.4" fill="url(#trail)"/><circle r="3.6" fill="#ffd6c8"/></g></g>
    <g className="burst" style={d(0)}>{sparks.map((s, i) => <line key={i} x1="3" y1="0" x2={s.l} y2="0" transform={`rotate(${s.a - 180 + ang})`} stroke="#ff8a78" strokeWidth="1.8" strokeLinecap="round"/>)}<circle r="6" fill="#ffd0c4"/></g>
    <g transform={`translate(${-f(x)} ${-f(y)})`}>
      <path className="ripple" d={arc(hit - 26, hit + 26)} style={d(0)} fill="none" stroke="#7ee9ff" strokeWidth="3.2" strokeLinecap="round"/>
      <path className="react" d={arc(hit - 52, hit + 52, DOME.r - 6)} style={d(.05)} fill="none" stroke="#22d3ee" strokeWidth="9" strokeOpacity=".25" strokeLinecap="round"/></g>
  </g>
}
const WAVES = [[{ hit: 205, ang: 24 }, { hit: 196, ang: 18, o: .25 }, { hit: 187, ang: 13, o: .5 }, { hit: 178, ang: 8, o: .75 }], [{ hit: 200, ang: 30 }], [{ hit: 186, ang: 22 }, { hit: 208, ang: 34, o: .4 }], [{ hit: 193, ang: 28 }]]

export default function Scene({ wave, animate }) {
  const threats = animate ? WAVES[wave % WAVES.length] : []
  const base = wave === 0 ? 2.4 : 0
  return <svg className="scene" viewBox="0 0 1671 941" preserveAspectRatio="xMidYMid slice" aria-hidden="true" focusable="false">
    <defs>
      <linearGradient id="sky" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stopColor="#03060a"/><stop offset=".55" stopColor="#07101a"/><stop offset=".8" stopColor="#0d2133"/><stop offset="1" stopColor="#0d2133"/></linearGradient>
      <linearGradient id="water" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stopColor="#0a1a28"/><stop offset="1" stopColor="#03070b"/></linearGradient>
      <linearGradient id="towerFill" x1="0" x2="1"><stop offset="0" stopColor="#0a131e"/><stop offset=".5" stopColor="#101e2f"/><stop offset="1" stopColor="#09111b"/></linearGradient>
      <linearGradient id="spine" x1="0" y1="1" x2="0" y2="0"><stop offset="0" stopColor="#22d3ee" stopOpacity=".9"/><stop offset="1" stopColor="#22d3ee" stopOpacity=".15"/></linearGradient>
      <linearGradient id="spire" x1="0" y1="1" x2="0" y2="0"><stop offset="0" stopColor="#bff6ff"/><stop offset="1" stopColor="#22d3ee" stopOpacity="0"/></linearGradient>
      <linearGradient id="trail" gradientUnits="userSpaceOnUse" x1="-200" x2="7"><stop offset="0" stopColor="#ef4444" stopOpacity="0"/><stop offset=".8" stopColor="#ef4444"/><stop offset="1" stopColor="#ffd6c8"/></linearGradient>
      <linearGradient id="haze" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stopColor="#1a4560" stopOpacity="0"/><stop offset="1" stopColor="#1a4560" stopOpacity=".28"/></linearGradient>
      <radialGradient id="domeFill" cx="1039" cy="583" r="295" gradientUnits="userSpaceOnUse"><stop offset=".6" stopColor="#22d3ee" stopOpacity=".01"/><stop offset=".9" stopColor="#22d3ee" stopOpacity=".07"/><stop offset="1" stopColor="#7ee9ff" stopOpacity=".3"/></radialGradient>
      <linearGradient id="fade" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stopColor="#fff" stopOpacity=".55"/><stop offset="1" stopColor="#fff" stopOpacity="0"/></linearGradient>
      <mask id="rfm"><rect x="0" y={WATER} width="1671" height="202" fill="url(#fade)"/></mask>
      <clipPath id="dclip"><path d={DP + 'Z'}/></clipPath>
      <pattern id="win" width="9" height="11" patternUnits="userSpaceOnUse"><rect x="2" y="3" width="3" height="5" fill="#7ee9ff" opacity=".55"/></pattern>
      <pattern id="rip" width="40" height="16" patternUnits="userSpaceOnUse"><rect width="40" height="3.5" fill="#04080d"/><rect y="8" width="22" height="1.6" fill="#04080d" opacity=".7"/></pattern>
      <g id="fortress"><Fortress/></g>
      <g id="cityFar"><City d={FAR} fill="#0c1826"/></g>
      <g id="domeRim"><path d={DP} fill="none" stroke="#7ee9ff" strokeWidth="2" strokeOpacity=".7"/></g>
    </defs>
    <g className="sc">
      <rect width="1671" height="941" fill="url(#sky)"/>
      <g className="p1">{STARS.map((s, i) => <circle key={i} cx={f(s[0])} cy={f(s[1])} r={s[2]} fill="#cfe9f2" opacity={s[3]}/>)}
        {CLOUDS.map((layer, li) => <g key={li} className={'cloud c' + li}>{layer.map((c, i) => <ellipse key={i} cx={c[0]} cy={c[1]} rx={c[2]} ry={c[3]} transform={`rotate(${c[4]} ${c[0]} ${c[1]})`} fill="#0f1d2d" opacity={.55 - li * .08}/>)}</g>)}</g>
      <rect y="560" width="1671" height={WATER - 560} fill="url(#haze)"/>
      <g className="p2"><use href="#cityFar"/><City d={NEAR} fill="#111f31"/></g>
      <rect y={BASE} width="1671" height={WATER - BASE} fill="#060c13"/>
      <g fill="#e3a559" opacity=".6">{shore.map((p, i) => <rect key={i} x={f(p[0])} y={f(p[1])} width="2" height="2"/>)}</g>

      <g className="p3">
        <path className="ring" d={ringD(false)} transform={`rotate(${RING.rot} ${RING.cx} ${RING.cy})`} pathLength="1" fill="none" stroke="#5fd9ee" strokeOpacity=".5" strokeWidth="1.6"/>
        <use href="#fortress" className="fort"/>
        <g className="spinerun"><rect x={FX - 4} y="300" width="8" height="90" fill="#bff6ff" opacity=".8"/></g>
        <g clipPath="url(#dclip)" className="dwire" fill="none" stroke="#7ee9ff" strokeOpacity=".16" strokeWidth="1">
          {[.25, .5, .75].map(k => <ellipse key={k} cx={DOME.cx} cy={DOME.cy} rx={DOME.r * k} ry={DOME.r}/>)}<path d={`M${DOME.cx} ${DOME.cy - DOME.r}V${BASE}`}/>
          {[-.7, -.4, -.1, .2, .5].map(s => { const rx = DOME.r * Math.sqrt(1 - s * s); return <ellipse key={s} cx={DOME.cx} cy={DOME.cy + DOME.r * s} rx={f(rx)} ry={f(rx * .2)}/> })}</g>
        <path className="dfill" d={DP + 'Z'} fill="url(#domeFill)"/>
        <path className="rim" d={DP} pathLength="1" fill="none" stroke="#7ee9ff" strokeWidth="2.2" strokeOpacity=".8"/>
        <path className="rim rimglow" d={DP} pathLength="1" fill="none" stroke="#22d3ee" strokeWidth="7" strokeOpacity=".12"/>
        <path className="ring" d={ringD(true)} transform={`rotate(${RING.rot} ${RING.cx} ${RING.cy})`} pathLength="1" fill="none" stroke="#7ee9ff" strokeOpacity=".7" strokeWidth="1.8"/>
        <path className="ringhl" d={ringD(true)} transform={`rotate(${RING.rot} ${RING.cx} ${RING.cy})`} pathLength="1" fill="none" stroke="#d6faff" strokeWidth="2.6" strokeLinecap="round"/>
        <g key={wave}>{threats.map((t, i) => <Threat key={i} hit={t.hit} ang={t.ang} t0={base + (t.o || 0)}/>)}</g>
      </g>

      <rect y={WATER} width="1671" height={941 - WATER} fill="url(#water)"/>
      <g className="refl" mask="url(#rfm)">
        <use href="#cityFar" transform={`translate(0 ${2 * WATER - 4}) scale(1 -1)`} opacity=".5"/>
        <use href="#fortress" transform={`translate(0 ${2 * WATER - 4}) scale(1 -1)`} opacity=".6"/>
        <use href="#domeRim" transform={`translate(0 ${2 * WATER - 4}) scale(1 -1)`} opacity=".5"/>
        <rect x={FX - 22} y={WATER} width="44" height="200" fill="#22d3ee" opacity=".22"/>
        {reflect.map((p, i) => <rect key={i} x={f(p[0])} y={WATER + 2} width="1.6" height={f(p[1])} fill="#e3a559" opacity=".35"/>)}
        <rect className="ripples" x="0" y={WATER - 12} width="1671" height="230" fill="url(#rip)"/>
      </g>
    </g>
  </svg>
}
